    /// - POST /libs/granite/security/post/truststore
    /// - BASIC:
    /// - type: http
    /// - name: aemAuth
    /// - parameter operation: (query)  (optional)
    /// - parameter newPassword: (query)  (optional)
    /// - parameter rePassword: (query)  (optional)
    /// - parameter keyStoreType: (query)  (optional)
    /// - parameter removeAlias: (query)  (optional)
    /// - parameter certificate: (form)  (optional)
    /// - returns: AnyPublisher<String, Error> 
    open func postTruststore(operation: String? = nil, newPassword: String? = nil, rePassword: String? = nil, keyStoreType: String? = nil, removeAlias: String? = nil, certificate: Data? = nil) -> AnyPublisher<String, Error> {
        Deferred {
            Result<URLRequest, Error> {
                guard let baseURL = self.transport.baseURL ?? self.baseURL else {
                    throw OpenAPITransportError.badURLError()
                }
                let localVarPath = "/libs/granite/security/post/truststore"
                let localVarURL = baseURL.appendingPathComponent(localVarPath)
                var components = URLComponents(url: localVarURL, resolvingAgainstBaseURL: false)
                var queryItems: [URLQueryItem] = []
                if let operation = operation { queryItems.append(URLQueryItem(name: ":operation", value: operation)) } 
                if let newPassword = newPassword { queryItems.append(URLQueryItem(name: "newPassword", value: newPassword)) } 
                if let rePassword = rePassword { queryItems.append(URLQueryItem(name: "rePassword", value: rePassword)) } 
                if let keyStoreType = keyStoreType { queryItems.append(URLQueryItem(name: "keyStoreType", value: keyStoreType)) } 
                if let removeAlias = removeAlias { queryItems.append(URLQueryItem(name: "removeAlias", value: removeAlias)) } 
                components?.queryItems = queryItems
                guard let requestURL = components?.url else {
                    throw OpenAPITransportError.badURLError()
                }
                var request = URLRequest(url: requestURL)
                request.httpMethod = "POST"
                let multipartBoundary = String(format: "Boundary+%08X%08X", arc4random(), arc4random())
                var multipartData = Data()
				if let certificate = certificate {
					let certificateHeader = "--\(multipartBoundary)\r\n"
					    .appending("Content-Disposition:form-data; name=\"certificate\"; filename=\"certificate\"\r\n")
					    .appending("\r\n")
					multipartData.append(certificateHeader.data(using: .utf8) ?? Data())
					multipartData.append(certificate)
				}

                multipartData.append("\r\n--\(multipartBoundary)--\r\n".data(using: .utf8) ?? Data())
                request.httpBody = multipartData
                request.setValue("\(multipartData.count)", forHTTPHeaderField: "Content-Length")
                request.setValue("multipart/form-data; boundary=\(multipartBoundary)", forHTTPHeaderField: "Content-Type")
                return request
            }.publisher
        }.flatMap { request -> AnyPublisher<String, Error> in 
            return self.transport.send(request: request)
                .tryMap { response in
                    try self.decoder.decode(String.self, from: response.data)
                }
                .eraseToAnyPublisher()
        }.eraseToAnyPublisher()
    }


